import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, SessionUsage } from 'claude-code'

import type { Context, Stats } from '../types'
import { MESSAGES, resolveLocale } from './i18n'
import type { Locale, WeatherKey } from './i18n'

const MAX_BARS = 24
const BAR_CHARS = ['▁', '▂', '▃', '▄', '▅', '▆', '▇', '█']
const GAUGE_WIDTH = 20

const EMPTY: Stats = { history: [], last: 0, total: 0, lastCacheRead: 0, context: null }

const stats = atom({ plugin: 'context-weather', key: 'stats' } as const, EMPTY)
const isHidden = atom({ plugin: 'context-weather', key: 'isHidden' } as const, false)
const locale = atom({ plugin: 'context-weather', key: 'locale' } as const, 'en' as Locale)

type Weather = { icon: string; key: WeatherKey; color: string }

/**
 * The weather for the context usage: up to 25% clear skies, up to 50% cloudy,
 * up to 75% rainy, up to 90% thunder (between rain and storm), above 90% storm.
 */
export function weatherFor(percent: number): Weather {
  if (percent <= 25) return { icon: '☀️', key: 'clear', color: '#F5B700' }
  if (percent <= 50) return { icon: '⛅', key: 'cloudy', color: '#8FA3B8' }
  if (percent <= 75) return { icon: '🌧️', key: 'rainy', color: '#3B82F6' }
  if (percent <= 90) return { icon: '🌩️', key: 'thunder', color: '#F59E0B' }
  return { icon: '⛈️', key: 'storm', color: '#EF4444' }
}

/** 1234 -> "1.2k"; 1234567 -> "1.23M"; below a thousand, the whole number. */
export function formatTokens(n: number, decimal = '.'): string {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(2).replace('.', decimal)}M`
  if (n >= 1_000) return `${(n / 1_000).toFixed(1).replace('.', decimal)}k`
  return String(Math.round(n))
}

/** One vertical bar per turn, scaled to the largest in the series. */
export function sparkline(values: readonly number[]): string {
  const max = Math.max(0, ...values)
  if (max === 0) return values.map(() => BAR_CHARS[0]).join('')
  return values
    .map(v => BAR_CHARS[Math.min(BAR_CHARS.length - 1, Math.round((v / max) * (BAR_CHARS.length - 1)))])
    .join('')
}

/** The context gauge, filled up to the percentage. */
export function gauge(percent: number): { filled: string; empty: string } {
  const cells = Math.max(0, Math.min(GAUGE_WIDTH, Math.round((percent / 100) * GAUGE_WIDTH)))
  return { filled: '█'.repeat(cells), empty: '░'.repeat(GAUGE_WIDTH - cells) }
}

function contextFrom(usage: SessionUsage): Context | null {
  const { tokens, window, percent } = usage.context
  if (tokens === undefined || percent === undefined) return null
  return { tokens, window, percent }
}

/** Shows or hides the band; the reply names the command as it was typed. */
async function toggle($: EngineInterface, command: string) {
  const hidden = await update($, isHidden, h => !h)
  const m = MESSAGES[await read($, locale)]

  return { text: hidden ? m.hidden(command) : m.shown }
}

export const register: Register = (on, options) => {
  on('session.start', async ($, e, next) => {
    // Detection is best effort: a source that cannot be read counts as unset.
    const settings = await $.settings.read().catch(() => ({}) as Record<string, unknown>)
    const lang = await $.env.get('LANG').catch(() => undefined)
    const resolved = resolveLocale(options.language, settings.language, lang)
    await update($, locale, () => resolved)

    await $.command.register({ name: 'context-weather', description: MESSAGES[resolved].commandDescription })
    // Alias for Portuguese speakers, always described in Portuguese.
    await $.command.register({ name: 'clima-contexto', description: MESSAGES['pt-BR'].commandDescription })

    const context = contextFrom(await $.session.usage())
    if (context) await update($, stats, s => ({ ...s, context }))

    return next(e)
  })

  on('command.run', { command: 'context-weather' }, $ => toggle($, 'context-weather'))
  on('command.run', { command: 'clima-contexto' }, $ => toggle($, 'clima-contexto'))

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    if (e.agentId !== undefined) return result

    const usage = e.usage
    const spent = usage ? usage.input_tokens + usage.cache_creation_input_tokens + usage.output_tokens : 0
    const cacheRead = usage ? usage.cache_read_input_tokens : 0
    const context = contextFrom(await $.session.usage())

    await update($, stats, s => ({
      history: [...s.history, spent].slice(-MAX_BARS),
      last: spent,
      total: s.total + spent,
      lastCacheRead: cacheRead,
      context: context ?? s.context,
    }))

    return result
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || (await read($, isHidden))) return next(e)

    const s = await read($, stats)
    if (s.context === null) return next(e)

    const m = MESSAGES[await read($, locale)]
    const fmt = (n: number) => formatTokens(n, m.decimal)
    const { Box, Button, Text } = $.ui.resolve(e)
    const weather = weatherFor(s.context.percent)
    const bar = gauge(s.context.percent)
    const bars = s.history.length > 0 ? sparkline(s.history) : '—'

    return (
      <Box flexDirection="column">
        <Box>
          <Text color={weather.color} bold={s.context.percent > 90}>
            {weather.icon} {m.weather[weather.key]}{'  '}
          </Text>
          <Text color={weather.color}>{bar.filled}</Text>
          <Text dimColor>{bar.empty}</Text>
          <Text>
            {' '}
            {s.context.percent}% · {fmt(s.context.tokens)} / {fmt(s.context.window)} {m.tokensInContext}{'  '}
          </Text>
          <Button key="hide" label={m.hide} onPress={() => update($, isHidden, () => true)} />
        </Box>
        <Box>
          <Text dimColor>{m.tokensPerTurn} </Text>
          <Text color="#22D3EE">{bars}</Text>
          <Text dimColor>
            {'  '}· {m.last}: {fmt(s.last)}
            {s.lastCacheRead > 0 ? ` (${m.cacheRead(fmt(s.lastCacheRead))})` : ''} · {m.session}:{' '}
            {fmt(s.total)}
          </Text>
        </Box>
      </Box>
    )
  })
}

