export type Context = { tokens: number; window: number; percent: number }

export type Stats = {
  /** New tokens (input + cache written + output) of the latest turns, most recent last. */
  history: number[]
  /** New tokens of the last turn. */
  last: number
  /** Sum of the new tokens of every turn in the session. */
  total: number
  /** Cache reads of the last turn (context read again, not counted in last). */
  lastCacheRead: number
  /** The context at the end of the last turn. */
  context: Context | null
}

declare module 'claude-code' {
  interface PluginState {
    'context-weather': { stats: Stats; isHidden: boolean; locale: 'en' | 'pt-BR' }
  }
}
